CREATE TABLE IF NOT EXISTS kb_user_memory (id BIGSERIAL PRIMARY KEY,user_id VARCHAR(100) NOT NULL,memory_type VARCHAR(30) NOT NULL,content TEXT NOT NULL,importance DECIMAL(3,2) DEFAULT .5,confidence DECIMAL(3,2) DEFAULT .5,expire_at TIMESTAMP,create_time TIMESTAMP NOT NULL DEFAULT NOW(),update_time TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kb_tool_trace (id BIGSERIAL PRIMARY KEY,trace_id VARCHAR(64),tool_name VARCHAR(100) NOT NULL,input_params JSONB,output_result JSONB,success BOOLEAN,error_msg TEXT,latency_ms INT,create_time TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kb_approval_record (id BIGSERIAL PRIMARY KEY,execution_id VARCHAR(64) NOT NULL,tool_name VARCHAR(100) NOT NULL,tool_params JSONB,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',approved_by VARCHAR(100),approved_at TIMESTAMP,ttl_seconds INT DEFAULT 300,create_time TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kb_model_health (id BIGSERIAL PRIMARY KEY,model_name VARCHAR(100) NOT NULL,model_type VARCHAR(20) NOT NULL,provider VARCHAR(50) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'CLOSED',priority INT DEFAULT 0,fail_count INT DEFAULT 0,success_count INT DEFAULT 0,last_error TEXT,opened_at TIMESTAMP,next_probe_at TIMESTAMP,update_time TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(model_name,model_type));
